describe('ZIP Code Auto-Format Feature', () => {
  beforeEach(() => {
    cy.visit('/form');
    cy.get('[data-testid="zip-code-input"]').as('zipInput');
  });

  it('should auto-format ZIP code to XXXXX format as user types', () => {
    cy.get('@zipInput').type('12345');
    cy.get('@zipInput').should('have.value', '12345');

    cy.get('@zipInput').clear().type('1234');
    cy.get('@zipInput').should('have.value', '1234');

    cy.get('@zipInput').clear().type('123456');
    cy.get('@zipInput').should('have.value', '12345');
  });

  it('should auto-format ZIP+4 code to XXXXX-XXXX format as user types', () => {
    cy.get('@zipInput').type('123456789');
    cy.get('@zipInput').should('have.value', '12345-6789');

    cy.get('@zipInput').clear().type('12345678');
    cy.get('@zipInput').should('have.value', '12345-678');
  });

  it('should handle pasted ZIP code and auto-format correctly', () => {
    cy.get('@zipInput').invoke('val', '123456789').trigger('input');
    cy.get('@zipInput').should('have.value', '12345-6789');
  });

  it('should reject non-numeric characters', () => {
    cy.get('@zipInput').type('1234a5');
    cy.get('@zipInput').should('have.value', '12345');

    cy.get('@zipInput').clear().type('123-45');
    cy.get('@zipInput').should('have.value', '12345');
  });

  it('should handle backspace and deletion correctly', () => {
    cy.get('@zipInput').type('12345-6789');
    cy.get('@zipInput').type('{backspace}{backspace}');
    cy.get('@zipInput').should('have.value', '12345-67');

    cy.get('@zipInput').clear();
    cy.get('@zipInput').should('have.value', '');
  });

  it('should display validation error for incomplete ZIP code on blur', () => {
    cy.get('@zipInput').type('123');
    cy.get('@zipInput').blur();
    cy.get('[data-testid="zip-error-message"]').should('be.visible').and('contain', 'ZIP code must be at least 5 digits');
  });

  it('should clear validation error when valid ZIP code is entered', () => {
    cy.get('@zipInput').type('123');
    cy.get('@zipInput').blur();
    cy.get('[data-testid="zip-error-message"]').should('be.visible');

    cy.get('@zipInput').clear().type('12345');
    cy.get('[data-testid="zip-error-message"]').should('not.exist');
  });

  it('should maintain cursor position during auto-formatting', () => {
    cy.get('@zipInput').type('12345');
    cy.get('@zipInput').should('have.value', '12345');

    cy.get('@zipInput').type('6789');
    cy.get('@zipInput').should('have.value', '12345-6789');
  });

  it('should handle edge case of exactly 5 digits without dash', () => {
    cy.get('@zipInput').type('12345');
    cy.get('@zipInput').should('have.value', '12345');
    cy.get('@zipInput').should('not.contain', '-');
  });

  it('should handle edge case of exactly 9 digits with dash', () => {
    cy.get('@zipInput').type('123456789');
    cy.get('@zipInput').should('have.value', '12345-6789');
  });
});
